import { Accordion, Separator, Text } from "@chakra-ui/react";
import { RasaCodeBlock } from "../../RasaCodeBlock";
import type { ConversationEvent } from "../../types";
import { CommonEventInfo, DetailView, EventAccordionItem, InfoField } from "./blocks";

interface SlotEventInfoProps {
  event: ConversationEvent;
  onClose: () => void;
}

export const SlotEventInfo = ({ event, onClose }: SlotEventInfoProps) => {
  return (
    <DetailView title="Slot event" onClose={onClose}>
      <InfoField label="Slot name" data-testid="event-slot-or-flow-name">
        <Text textStyle="sm">{event.name || "-"}</Text>
      </InfoField>

      <InfoField label="Value" data-testid="event-slot-value">
        <RasaCodeBlock
          code={JSON.stringify(event.slotValue, null, 2)}
          data-testid="event-mcp-tool-result"
        />
      </InfoField>

      <Separator mt="2" />

      <Accordion.Root collapsible multiple>
        <EventAccordionItem title="Event details" value="event-details">
          <CommonEventInfo event={event} />
        </EventAccordionItem>
      </Accordion.Root>
    </DetailView>
  );
};
